import React from 'react';
import '../styles/Servicios.css';

const DeclaracionRentas = () => (
  <div className="servicios-container">
    <h2 className="servicios-title">Declaración de Rentas</h2>
    <p>Asesoría y gestión profesional para la declaración de renta de personas naturales y jurídicas, cumpliendo con la normativa vigente y optimizando tus beneficios fiscales.</p>
  </div>
);

export default DeclaracionRentas;
